    R,C=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c]==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<R and 0<=xx<C and (yy,xx) not in seen and grid[yy][xx]==grid[r][c]:
              seen.add((yy,xx));q.append((yy,xx))
        comps.append((grid[r][c],comp))
    # Determine replacement color from small reference object: the smallest isolated 3-cell component
    # is the color key. Large repeated irregular shapes of color 6 take the key color.
    keys=[(col,co) for col,co in comps if len(co)==3]
    keycol=keys[0][0] if keys else 0
    for col,co in comps:
      if col==6:
        for r,c in co: out[r][c]=keycol
    return out
